plan:
phase("Grade every solution once")
grades = flatten(parallel([lambda b=b: grade(b) for b in batches(items, 40)]))
grade_by_id = {g["id"]: g for g in grades}

phase("Calculator-flagged items")
flagged = [i for i in items if calculator_flags(i) > 0]
suspects = [i for i in flagged if i in grade_by_id and not grade_by_id[i]["wrong"]]

if flagged:
    first = flatten(parallel([lambda b=b: recheck(b, lens="calculator", model="judge") for b in batches(flagged, 40)]))
    if suspects:
        second = flatten(parallel([lambda b=b: recheck(b, lens="calculator", model="fast") for b in batches(suspects, 40)]))
    else:
        second = []
    suspect_set = {i: True for i in suspects}
    extra = [g for g in first + second if g["id"] in suspect_set]
else:
    extra = []

phase("Merge and report")
result = class_report(merge(grades + extra))
